// Spirit level: the frame's accelerometer as a level. Lying flat it is a
// bullseye, its bubble drifting to the high side; standing up it is a tube
// along the side of the picture that is level, and says how many degrees off
// it is. A tap (or the Action key) zeroes it where it rests; a long press
// takes the zero away.
//
// A fast screen draws it twenty times a second, the reading smoothed. E-paper
// redraws when the reading moves by a degree (each render is a refresh, and
// one that changed nothing changes nothing on the glass). A frame without an
// accelerometer shows a demo, the bubble wandering, and says so.

type Vec = { x: number; y: number; z: number }

// Smoothed between renders on a fast screen.
let smooth: Vec | null = null

const accelerometer = (): Vec | null => (typeof frameos.accelerometer === 'function' ? frameos.accelerometer() : null)

const DEG = 180 / Math.PI

/** The zero the person set: an offset for each kind of level. */
function zeroOf(app: any): { flatX: number; flatY: number; tube: number } {
  const z = app.state.zero
  if (z && typeof z === 'object') {
    return { flatX: Number(z.flatX) || 0, flatY: Number(z.flatY) || 0, tube: Number(z.tube) || 0 }
  }
  return { flatX: 0, flatY: 0, tube: 0 }
}

/** What the level reads from a gravity vector: flat or standing, and how far off. */
function readLevel(g: Vec) {
  const inPlane = Math.sqrt(g.x * g.x + g.y * g.y)
  const flat = Math.abs(g.z) > inPlane * 1.2
  // Standing: the side of the picture nearest level is the tube's. The
  // quarter turn the picture stands at, and the angle off it.
  const roll = Math.atan2(g.x, g.y) * DEG
  const quarter = Math.round(roll / 90)
  const vertical = (quarter & 1) !== 0
  const along = vertical ? g.y : g.x
  const tubeAngle = Math.asin(Math.max(-1, Math.min(1, along / Math.max(inPlane, 0.001)))) * DEG
  // Flat: how far each way the surface leans, in degrees.
  const flatX = Math.atan2(g.x, Math.abs(g.z)) * DEG
  const flatY = Math.atan2(g.y, Math.abs(g.z)) * DEG
  return { flat, vertical, tubeAngle, flatX, flatY }
}

/** A wandering bubble for a frame with no accelerometer. */
function demo(now: number): Vec {
  const t = now / 1000
  return { x: Math.sin(t * 0.7) * 0.12 + Math.sin(t * 1.9) * 0.04, y: Math.cos(t * 0.5) * 0.1, z: -1 }
}

const fmt = (deg: number, fine: boolean) => {
  const a = Math.abs(deg)
  return (fine ? (Math.round(a * 10) / 10).toFixed(1) : String(Math.round(a))) + '°'
}

export function get(app: any, context: any) {
  const W = context.imageWidth || app.frame.width
  const H = context.imageHeight || app.frame.height
  const round = context.round === true
  const fast = app.frame.fast ?? !app.frame.paper
  const now = Date.now()
  const real = accelerometer()
  const raw = real || demo(now)
  if (fast && smooth && real) {
    const k = 0.35
    smooth = { x: smooth.x + (raw.x - smooth.x) * k, y: smooth.y + (raw.y - smooth.y) * k, z: smooth.z + (raw.z - smooth.z) * k }
  } else {
    smooth = { x: raw.x, y: raw.y, z: raw.z }
  }
  const zero = zeroOf(app)
  const r = readLevel(smooth)
  // E-paper shows whole degrees, so a reading that wobbles redraws nothing.
  const q = (deg: number) => (fast ? deg : Math.round(deg))
  const flatX = q(r.flatX - zero.flatX)
  const flatY = q(r.flatY - zero.flatY)
  const tube = q(r.tubeAngle - zero.tube)

  const S = Math.min(W, H)
  const cx = W / 2
  const cy = H / 2
  const paper = !fast
  const ink = paper ? '#000000' : '#e8eef2'
  const back = paper ? '#ffffff' : '#10161d'
  const glass = paper ? '#ffffff' : '#1d2a33'
  const fluid = paper ? '#ffffff' : '#b9e04a'
  const bubble = paper ? '#000000' : '#f6ffd8'
  const accent = paper ? '#000000' : '#7fd1b9'
  const level = r.flat ? Math.hypot(flatX, flatY) < 0.5 : Math.abs(tube) < 0.5
  const font = Math.round(S * 0.13)
  const small = Math.max(14, Math.round(S * (fast ? 0.045 : 0.055)))

  let body
  let reading
  if (r.flat) {
    // A bullseye: the bubble goes to the high side, all the way out at 10°.
    const R = S * (round ? 0.34 : 0.32)
    const b = S * 0.085
    const reach = R - b - S * 0.01
    let bx = -flatX / 10
    let by = -flatY / 10
    const m = Math.hypot(bx, by)
    if (m > 1) {
      bx /= m
      by /= m
    }
    const ox = cx + bx * reach
    const oy = cy - S * 0.04 + by * reach
    const y0 = cy - S * 0.04
    body = (
      <g>
        <circle cx={cx} cy={y0} r={R} fill={fluid} stroke={ink} strokeWidth={S * 0.012} />
        <circle cx={cx} cy={y0} r={b * 1.25} fill="none" stroke={ink} strokeWidth={S * 0.008} />
        <circle cx={cx} cy={y0} r={R * 0.62} fill="none" stroke={ink} strokeWidth={S * 0.004} strokeDasharray={`${S * 0.012} ${S * 0.012}`} />
        <line x1={cx - R} y1={y0} x2={cx + R} y2={y0} stroke={ink} strokeWidth={S * 0.003} />
        <line x1={cx} y1={y0 - R} x2={cx} y2={y0 + R} stroke={ink} strokeWidth={S * 0.003} />
        <circle cx={ox} cy={oy} r={b} fill={bubble} stroke={paper ? 'none' : '#ffffff'} strokeWidth={S * 0.004} />
        {paper ? null : <circle cx={ox - b * 0.35} cy={oy - b * 0.35} r={b * 0.25} fill="#ffffff" opacity={0.8} />}
      </g>
    )
    reading = level ? 'Level' : `${fmt(Math.hypot(flatX, flatY), fast)}`
  } else {
    // A tube along the level side of the picture: the bubble runs to the
    // high end, all the way at 5°.
    const vertical = r.vertical
    const span = round ? S * 0.62 : (vertical ? H : W) * 0.78
    const thick = S * 0.17
    const len = vertical ? thick : span
    const tall = vertical ? span : thick
    const x0 = cx - len / 2
    const y0 = cy - (vertical ? 0 : S * 0.05) - tall / 2
    const bl = thick * 1.5
    const reach = (span - bl) / 2 - S * 0.02
    const t = Math.max(-1, Math.min(1, -tube / 5)) * reach
    const bxc = vertical ? cx : cx + t
    const byc = vertical ? cy + t : y0 + tall / 2
    const mark = bl / 2 + S * 0.01
    body = (
      <g>
        <rect x={x0} y={y0} width={len} height={tall} rx={thick / 2} fill={fluid} stroke={ink} strokeWidth={S * 0.012} />
        {vertical ? (
          <g>
            <line x1={x0 - S * 0.03} y1={cy - mark} x2={x0 + len + S * 0.03} y2={cy - mark} stroke={ink} strokeWidth={S * 0.008} />
            <line x1={x0 - S * 0.03} y1={cy + mark} x2={x0 + len + S * 0.03} y2={cy + mark} stroke={ink} strokeWidth={S * 0.008} />
          </g>
        ) : (
          <g>
            <line x1={cx - mark} y1={y0 - S * 0.03} x2={cx - mark} y2={y0 + tall + S * 0.03} stroke={ink} strokeWidth={S * 0.008} />
            <line x1={cx + mark} y1={y0 - S * 0.03} x2={cx + mark} y2={y0 + tall + S * 0.03} stroke={ink} strokeWidth={S * 0.008} />
          </g>
        )}
        <ellipse cx={bxc} cy={byc} rx={vertical ? thick * 0.32 : bl / 2} ry={vertical ? bl / 2 : thick * 0.32} fill={bubble} />
      </g>
    )
    reading = level ? 'Level' : fmt(tube, fast)
  }

  const caption = !real
    ? 'No accelerometer: a demo'
    : r.flat
      ? level ? 'Flat and level' : 'Lying down'
      : level ? 'Straight' : r.vertical ? (tube > 0 ? 'Top side high' : 'Bottom side high') : tube > 0 ? 'Left side high' : 'Right side high'
  const readingY = r.flat ? cy + S * 0.42 : cy + S * 0.28
  // The fast screen keeps going; e-paper looks again in a second, the demo
  // on e-paper stays still.
  if (!fast && !real) frameos.setNextSleep(3600)
  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <rect x={0} y={0} width={W} height={H} fill={back} />
      {body}
      <text x={cx} y={readingY} fontSize={font} fontWeight="bold" textAnchor="middle" fill={level ? accent : ink}>
        {reading}
      </text>
      <text x={cx} y={round ? cy - S * 0.4 : Math.max(small * 1.6, cy - S * 0.44)} fontSize={small} textAnchor="middle" fill={ink}>
        {caption}
      </text>
    </svg>
  )
}

export function onEvent(app: any, context: any) {
  const e = context.event
  const p = context.payload || {}
  const zeroHere = e === 'tap' || (e === 'button' && p.action === 'press' && p.role === 'primary') ||
    (e === 'keyDown' && (p.code === 'Space' || p.code === 'Enter'))
  if (zeroHere) {
    const g = accelerometer()
    if (!g) return false
    const r = readLevel(smooth || g)
    frameos.setState('zero', { flatX: r.flat ? r.flatX : zeroOf(app).flatX, flatY: r.flat ? r.flatY : zeroOf(app).flatY, tube: r.flat ? zeroOf(app).tube : r.tubeAngle })
    return true
  }
  if (e === 'longPress' || (e === 'button' && p.action === 'longPress' && p.role === 'primary') || (e === 'keyDown' && p.code === 'Escape')) {
    frameos.setState('zero', null)
    return true
  }
  // A new position: draw it now, not at the next look.
  return e === 'orientation' || e === 'tilt'
}
